  ('business-development-executive-jobs', (select id from public.companies where slug = 'jobs-territory'), 'Business Development Executive', 'Coimbatore', 'onsite', 'full_time', 'junior', 360000, 600000, 'INR', 'Open and grow customer relationships for Jobs Territory, with training and a clear territory. This is a junior, full-time role based in Coimbatore (on-site).', array['Find and qualify prospects using Communication and CRM', 'Run calls and demos and follow up', 'Keep the CRM accurate', 'Share what customers tell you with the team']::text[], array['Good at Communication and CRM', 'Resilient and organised', 'Fluent in English; local language is a plus', '0 to 2 years of experience or strong projects']::text[], array['Communication', 'CRM', 'Negotiation', 'Cold Calling', 'Presentation']::text[], now() - interval '24 hours', now() + interval '21 days'),
  ('customer-support-specialist-jobs', (select id from public.companies where slug = 'jobs-territory'), 'Customer Support Specialist', 'Coimbatore', 'onsite', 'full_time', 'junior', 280000, 440000, 'INR', 'Answer Jobs Territory customers quickly and kindly, and fix the cause where you can. This is a junior, full-time role based in Coimbatore (on-site).', array['Handle tickets and calls using Customer Support and Communication', 'Escalate with full details', 'Update help articles when answers change', 'Report recurring problems']::text[], array['Good at Customer Support and Communication', 'Clear spoken and written English', 'Willing to work some shifts', '0 to 2 years of experience or strong projects']::text[], array['Customer Support', 'Communication', 'Zendesk', 'Troubleshooting', 'Empathy']::text[], now() - interval '40 hours', now() + interval '16 days'),
  ('qa-engineer-mobile-tamarind', (select id from public.companies where slug = 'tamarind-health'), 'QA Engineer, Mobile', 'Chennai', 'hybrid', 'full_time', 'mid', 800000, 1300000, 'INR', 'Make sure what Tamarind Health ships works, by testing early and automating what repeats. This is a mid-level, full-time role based in Chennai (hybrid).', array['Write and maintain automated tests in Testing and Selenium', 'Test new features and reproduce reported bugs', 'Report issues clearly with steps and evidence', 'Improve how the team tests']::text[], array['Hands-on with Testing and Selenium', 'Methodical and curious about edge cases', 'Clear bug reports', '3 to 5 years of relevant experience']::text[], array['Testing', 'Selenium', 'Cypress', 'API Testing', 'SQL']::text[], now() - interval '52 hours', now() + interval '23 days'),
  ('react-native-developer-clinic-app-tamarind', (select id from public.companies where slug = 'tamarind-health'), 'React Native Developer, Clinic App', 'Chennai', 'hybrid', 'full_time', 'mid', 1200000, 1900000, 'INR', 'Build the mobile app Tamarind Health customers rely on, including on slow networks and older phones. This is a mid-level, full-time role based in Chennai (hybrid).', array['Build and release app features in React Native and TypeScript', 'Profile and fix slow screens and crashes', 'Work with backend engineers on APIs', 'Write tests for the flows that matter']::text[], array['Experience with React Native and TypeScript', 'You have published or demonstrated a mobile app', 'Patience for device and network quirks', '3 to 5 years of relevant experience']::text[], array['React Native', 'TypeScript', 'Android', 'REST APIs', 'Git']::text[], now() - interval '38 hours', now() + interval '26 days'),
  ('platform-engineer-brightwell', (select id from public.companies where slug = 'brightwell-labs'), 'Platform Engineer', 'Pune', 'remote', 'full_time', 'senior', 2400000, 3600000, 'INR', 'Keep Brightwell Labs''s systems deployable and reliable, and make the next release boring. This is a senior, full-time role working remotely.', array['Maintain build and deploy pipelines in Docker and Kubernetes', 'Automate infrastructure and cut manual steps', 'Respond to incidents and write the follow-ups', 'Watch cost and capacity']::text[], array['Working knowledge of Docker and Kubernetes', 'You can debug a failing deploy calmly', 'Basic scripting', '6 or more years of experience, with ownership of a significant system or area']::text[], array['Docker', 'Kubernetes', 'Linux', 'Terraform', 'CI/CD']::text[], now() - interval '64 hours', now() + interval '28 days'),
  ('technical-writer-brightwell', (select id from public.companies where slug = 'brightwell-labs'), 'Technical Writer', 'Pune', 'remote', 'full_time', 'mid', 900000, 1500000, 'INR', 'Write and edit what Brightwell Labs publishes: clear, accurate and worth reading. This is a mid-level, full-time role working remotely.', array['Write and edit articles and pages using Content Writing and Editing', 'Research topics and check facts', 'Work with design and marketing on campaigns', 'Track which pieces people read']::text[], array['Clear writing and strong editing', 'Experience with Content Writing and Editing', 'Samples we can read', '3 to 5 years of relevant experience']::text[], array['Content Writing', 'Editing', 'SEO', 'Research', 'Social Media']::text[], now() - interval '72 hours', now() + interval '24 days'),
  ('data-engineer-billing-orchard', (select id from public.companies where slug = 'orchard-cloud'), 'Data Engineer, Billing', 'Hyderabad', 'hybrid', 'full_time', 'mid', 1500000, 2400000, 'INR', 'Build the pipelines that give Orchard Cloud trustworthy data. This is a mid-level, full-time role based in Hyderabad (hybrid).', array['Build and monitor pipelines in SQL and Python', 'Model tables other teams can rely on', 'Find and fix data-quality problems at the source', 'Document datasets and owners']::text[], array['Strong in SQL and Python', 'You have moved data from messy to usable', 'Careful with details', '3 to 5 years of relevant experience']::text[], array['SQL', 'Python', 'Airflow', 'Kafka', 'Data Modeling']::text[], now() - interval '31 hours', now() + interval '27 days'),
  ('cloud-security-engineer-orchard', (select id from public.companies where slug = 'orchard-cloud'), 'Cloud Security Engineer', 'Hyderabad', 'hybrid', 'full_time', 'senior', 2800000, 4200000, 'INR', 'Protect Orchard Cloud and its customers by finding problems before others do. This is a senior, full-time role based in Hyderabad (hybrid).', array['Monitor alerts and investigate incidents using Networking and SIEM', 'Review systems and code for weaknesses', 'Write up findings with clear fixes', 'Help teams build securely']::text[], array['Knowledge of Networking and SIEM', 'Curious and careful, with a bias for evidence', 'Willing to work some shifts', '6 or more years of experience, with ownership of a significant system or area']::text[], array['Networking', 'SIEM', 'Incident Response', 'Linux', 'Python']::text[], now() - interval '83 hours', now() + interval '22 days'),
