insert into public.interview_insights (company_id, author_id, role_title, rounds, difficulty, outcome, experience, is_sample, created_at) values
  ((select id from public.companies where slug = 'indus-ledger'), null, 'Backend Engineer', 4, 4, 'offer', 'A recruiter screen, then a take-home building a small ledger API with idempotent writes. The technical round walked through my take-home line by line and asked how I would handle a retry storm. The final round was about how I work with risk and product people.', true, now() - interval '9 days'),
  ((select id from public.companies where slug = 'indus-ledger'), null, 'Data Analyst', 3, 3, 'rejected', 'SQL test first (window functions and a tricky join), then a case about default rates. Feedback afterwards said my SQL was fine but my case answer jumped to conclusions before checking the data.', true, now() - interval '18 days'),
  ((select id from public.companies where slug = 'tamarind-health'), null, 'Frontend Engineer', 3, 3, 'offer', 'Pairing session on a real accessibility bug in their booking flow. They cared more about how I reasoned and tested than about finishing. Fast replies at every stage.', true, now() - interval '27 days'),
  ((select id from public.companies where slug = 'tamarind-health'), null, 'QA Automation Engineer', 3, 2, 'no_answer', 'Friendly screen and a short test-writing exercise. Then silence for five weeks despite one follow-up.', true, now() - interval '36 days'),
  ((select id from public.companies where slug = 'aster-mobility'), null, 'React Native Developer', 4, 4, 'offer', 'Live coding in React Native with a flaky network simulation, then a system design round on offline sync. The mobile lead was very clear about what good looks like.', true, now() - interval '45 days'),
  ((select id from public.companies where slug = 'aster-mobility'), null, 'Growth Marketing Manager', 3, 3, 'withdrew', 'Three rounds with a presentation on a real funnel. I withdrew after the second salary conversation did not match the listing.', true, now() - interval '54 days'),
  ((select id from public.companies where slug = 'brightwell-labs'), null, 'Developer Advocate', 4, 3, 'rejected', 'Writing exercise, a recorded talk, and two interviews. They wanted evidence of a published track record; the feedback was kind and specific.', true, now() - interval '63 days'),
  ((select id from public.companies where slug = 'orchard-cloud'), null, 'Site Reliability Engineer', 5, 5, 'rejected', 'Five rounds including an on-call scenario and a Linux debugging session on a live box. Hard but fair, and the interviewers explained their reasoning afterwards.', true, now() - interval '72 days');
